<?php require 'config.php';require_login();$no=$conn->real_escape_string($_GET['no']??'');$r=$conn->query("SELECT p.*,tg.bulan,tg.tahun,w.nomor_pelanggan,w.nama,w.alamat,u.nama petugas FROM pembayaran p JOIN tagihan tg ON tg.id=p.tagihan_id JOIN warga w ON w.id=tg.warga_id JOIN users u ON u.id=p.petugas_id WHERE p.nomor_kwitansi='$no' LIMIT 1")->fetch_assoc();if(!$r)die('Kwitansi tidak ditemukan.');?>
<!doctype html><html lang="id"><head><meta charset="utf-8"><title>Kwitansi <?=e($no)?></title><link rel="stylesheet" href="assets/style.css"></head><body class="receipt"><div class="receiptbox"><div class="receipthead"><div><h2>♻️ IURAN SAMPAH</h2><p>Bukti Pembayaran Iuran</p></div><b><?=e($r['nomor_kwitansi'])?></b></div><hr><p><b>No. Pelanggan:</b> <?=e(format_nomor_pelanggan($r['nomor_pelanggan']))?></p><p><b>Nama:</b> <?=e($r['nama'])?></p><p><b>Alamat:</b> <?=e($r['alamat'])?></p><p><b>Periode:</b> <?=periode_label($r['bulan'],$r['tahun'])?></p><p><b>Tanggal:</b> <?=e($r['tanggal_bayar'])?></p><p><b>Metode:</b> <?=e($r['metode'])?></p><div class="amount"><?=rupiah($r['nominal'])?></div><p>Petugas: <?=e($r['petugas'])?></p><button class="btn primary" onclick="window.print()">🖨 Cetak</button></div></body></html>